use anyhow::{Context, Result, ensure};
use media_inference_lab::{
    process_scope::{self, CommandSpec, OwnedProcess, ProcessIdentity, Settlement},
    service_lifecycle::{observe_tcp_listeners, RecoveryBudget, RecoveryControl},
};
use serde_json::{Value, json};
use std::{cell::RefCell, collections::BTreeMap, io::{Read, Write}, net::{SocketAddr, TcpListener, TcpStream, UdpSocket}, os::fd::{FromRawFd, OwnedFd, AsRawFd}, rc::Rc, time::{Duration, Instant}};

fn emit(value: Value) { println!("{value}"); }

// Fixture ownership is enrolled before inspecting any fallible spawn/readiness result.
// Drop performs bounded identity-qualified settlement on success, failure and unwind.
struct Fixture {
    actor: OwnedProcess,
    identity: Option<ProcessIdentity>,
    end: Instant,
    settled: bool,
}
impl Fixture {
    fn start(mode: &str, address: &str, port: u16) -> Result<Self> {
        let end = Instant::now() + Duration::from_secs(12);
        let spec = CommandSpec {
            executable: std::env::current_exe()?,
            args: vec!["worker".into(), mode.into(), address.into(), port.to_string()],
            cwd: std::env::current_dir()?, environment: BTreeMap::new(),
        };
        let attempt = OwnedProcess::spawn_with_deadline(&spec, Instant::now() + Duration::from_secs(2), &mut || Ok(()))?;
        let fixture = Self { identity: attempt.process.identity().ok(), actor: attempt.process, end, settled: false };
        emit(json!({"fixture_enrolled":fixture.actor.pid(), "identity":fixture.identity, "mode":mode}));
        ensure!(attempt.failure.is_none(), "fixture spawn failed; owner retained for cleanup");
        Ok(fixture)
    }
    fn ready(&mut self) -> Result<Value> {
        let deadline = Instant::now() + Duration::from_secs(2);
        let mut output = Vec::new();
        loop {
            ensure!(Instant::now() < deadline, "fixture readiness deadline expired");
            let mut buffer = [0; 512];
            match self.actor.stdout.as_mut().context("fixture stdout missing")?.read(&mut buffer) {
                Ok(0) => anyhow::bail!("fixture closed readiness stream"),
                Ok(n) => {
                    ensure!(output.len() + n <= 4096, "fixture readiness overflow");
                    output.extend_from_slice(&buffer[..n]);
                    if output.ends_with(b"\n") { return Ok(serde_json::from_slice(&output)?); }
                }
                Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {}
                Err(e) => return Err(e.into()),
            }
            std::thread::sleep(Duration::from_millis(5));
        }
    }
    fn unchanged(&self) -> Result<()> {
        let original = self.identity.as_ref().context("fixture identity unavailable")?;
        let now = process_scope::verify_identity(original)?;
        ensure!(now.same_process(original) && now.state == process_scope::ProcessState::Running,
            "listener observation interfered with owned fixture");
        Ok(())
    }
    fn finish(&mut self) -> Result<()> {
        if self.settled { return Ok(()); }
        self.settled = true;
        let result = self.actor.settle(self.end, Duration::from_millis(100), &mut || Ok(()));
        emit(json!({"fixture_cleanup":self.actor.pid(), "identity":self.identity,
            "settlement":result.as_ref().ok(), "error":result.as_ref().err().map(|e| format!("{e:#}"))}));
        // A failed terminal receipt is never retried or upgraded to complete. For a
        // finite direct fixture child only, bounded waitpid may reap without control.
        if !result.as_ref().is_ok_and(|s| s.leader_reaped) {
            let mut reaped = false;
            while Instant::now() < self.end {
                let mut status = 0;
                let waited = unsafe { libc::waitpid(self.actor.pid() as i32, &mut status, libc::WNOHANG) };
                if waited == self.actor.pid() as i32 { reaped = true; break; }
                if waited < 0 { break; }
                std::thread::sleep(Duration::from_millis(10));
            }
            emit(json!({"fixture_finite_wait":self.actor.pid(), "leader_reaped":reaped,
                "does_not_clear_fork_uncertainty":true}));
        }
        let Settlement { complete, leader_reaped, group_absent, .. } = result?;
        ensure!(complete && leader_reaped && group_absent, "fixture cleanup incomplete");
        Ok(())
    }
}
impl Drop for Fixture { fn drop(&mut self) { let _ = self.finish(); } }

fn observe(label: &str, port: u16, owners: &[&Fixture], expected: &[u32]) -> Result<bool> {
    ensure!(port != 0 && port != 8000 && port != 7860, "forbidden fixture port");
    for owner in owners { owner.unchanged()?; }
    let start = Instant::now();
    let budget = Rc::new(RefCell::new(RecoveryBudget::new(Duration::from_secs(3), start + Duration::from_secs(5))));
    let mut recovery_tick = || Ok(());
    let mut recovery = RecoveryControl::new(budget.clone(), &mut recovery_tick);
    let result = observe_tcp_listeners(port, start + Duration::from_millis(500), &mut || Ok(()), &mut recovery);
    emit(json!({"case":label, "port":port, "elapsed_micros":start.elapsed().as_micros(),
        "observation":result.as_ref().ok(), "error":result.as_ref().err().map(|e| format!("{e:#}")),
        "failed_helpers":recovery.observations(), "recovery_complete":recovery.complete(),
        "global_visibility_certified":false}));
    for owner in owners { owner.unchanged()?; }
    emit(json!({"case":label,"non_interference":true,"owned_pids":owners.iter().map(|owner|owner.actor.pid()).collect::<Vec<_>>()}));
    let observation = match result {
        Ok(observation) => observation,
        Err(_) => {
            ensure!(recovery.complete(), "failed helper accounting remains incomplete");
            // Continue independent owned cases, never reinterpret this denial.
            return Ok(false);
        }
    };
    ensure!(observation.helper.complete && observation.helper.settlement.as_ref().is_some_and(|s|
        s.complete && s.leader_reaped && s.group_absent), "listener helper not completely settled");
    ensure!(recovery.observations().is_empty(), "successful poll grew shared receipt history");
    let mut actual: Vec<_> = observation.listeners.iter().map(|r| r.pid).collect();
    actual.sort_unstable();
    let mut expected = expected.to_vec(); expected.sort_unstable();
    ensure!(actual == expected, "owned listener selection mismatch; unknown contender is not controlled");
    for owner in owners { owner.unchanged()?; }
    Ok(true)
}

fn assigned(ready: &Value) -> Result<u16> {
    let port = ready["port"].as_u64().context("worker did not supply a port")?;
    ensure!(port > 0 && port <= u16::MAX as u64 && port != 8000 && port != 7860, "invalid fixture port");
    Ok(port as u16)
}
fn unsupported(ready: &Value) -> bool {
    ready["errno"].as_i64().is_some_and(|e| [libc::EAFNOSUPPORT, libc::EPROTONOSUPPORT, libc::EADDRNOTAVAIL].contains(&(e as i32)))
}
fn run() -> Result<()> {
    let mut qualified = true;
    emit(json!({"limits":["owned same-user observations only; no cross-user completeness certificate",
        "no native service/prefix/name query and no production ports", "500ms observation cap unchanged",
        "helper syscall cancellation not guaranteed; historical helper38672 remains incomplete",
        "IPv6/address reuse unsupported outcomes are not proof", "no lsof-specific fork exemption"]}));
    // The first loopback call is already retained as smoke-001; no retry-to-pass.
    for address in ["0.0.0.0", "::1", "::"] {
        let mut fixture = Fixture::start("listen", address, 0)?;
        let ready = fixture.ready()?;
        if address.contains(':') && unsupported(&ready) {
            emit(json!({"unsupported_ipv6":address,"errno":ready["errno"]}));
            fixture.finish()?;
            continue;
        }
        let port = assigned(&ready)?;
        qualified &= observe(address, port, &[&fixture], &[fixture.actor.pid()])?;
        fixture.finish()?;
        qualified &= observe("closed_owned_port", port, &[], &[])?;
    }
    let mut first = Fixture::start("listen", "127.0.0.1", 0)?;
    let port = assigned(&first.ready()?)?;
    qualified &= observe("original", port, &[&first], &[first.actor.pid()])?;
    let old_pid = first.actor.pid();
    first.finish()?;
    let mut replacement = Fixture::start("listen", "127.0.0.1", port)?;
    ensure!(assigned(&replacement.ready()?)? == port && replacement.actor.pid() != old_pid,
        "replacement identity/port invalid");
    qualified &= observe("replacement", port, &[&replacement], &[replacement.actor.pid()])?;
    let mut distinct = Fixture::start("listen", "127.0.0.2", port)?;
    let ready = distinct.ready()?;
    if unsupported(&ready) || ready["errno"].as_i64() == Some(libc::EADDRINUSE as i64) {
        emit(json!({"unsupported_distinct_address":true,"errno":ready["errno"]}));
    } else {
        ensure!(assigned(&ready)? == port, "distinct binding port changed");
        qualified &= observe("distinct_address_owners", port, &[&replacement, &distinct], &[replacement.actor.pid(), distinct.actor.pid()])?;
    }
    distinct.finish()?;
    replacement.finish()?;
    qualified &= observe("replacement_closed", port, &[], &[])?;
    for mode in ["bound", "established", "udp"] {
        let mut fixture = Fixture::start(mode, "127.0.0.1", 0)?;
        let port = assigned(&fixture.ready()?)?;
        qualified &= observe(mode, port, &[&fixture], &[])?;
        fixture.finish()?;
    }
    emit(json!({"owned_listener_smoke":if qualified {"passed"} else {"completed_with_denied_observations"}, "global_visibility_certified":false}));
    ensure!(qualified, "owned observation matrix completed with retained denials; no listener qualification claim");
    Ok(())
}

fn multiple_families() -> Result<()> {
    let mut ipv4 = Fixture::start("listen", "127.0.0.1", 0)?;
    let port = assigned(&ipv4.ready()?)?;
    let mut ipv6 = Fixture::start("listen", "::1", port)?;
    let ready = ipv6.ready()?;
    if unsupported(&ready) || ready["errno"].as_i64() == Some(libc::EADDRINUSE as i64) {
        emit(json!({"multiple_families_unsupported":true,"errno":ready["errno"]}));
        ipv6.finish()?;
        ipv4.finish()?;
        anyhow::bail!("multiple-family fixture unavailable");
    }
    ensure!(assigned(&ready)? == port, "multiple-family port changed");
    let qualified = observe("multiple_ipv4_ipv6_owners", port, &[&ipv4, &ipv6],
        &[ipv4.actor.pid(), ipv6.actor.pid()])?;
    ipv6.finish()?;
    ipv4.finish()?;
    ensure!(qualified, "multiple-family observation denied; no listener qualification claim");
    Ok(())
}

fn ready(port: u16) -> Result<()> {
    ensure!(port != 8000 && port != 7860, "kernel assigned excluded port");
    println!("{}", json!({"port":port})); std::io::stdout().flush()?;
    // Every worker is finite and nonforking even if its controller unwinds.
    std::thread::sleep(Duration::from_secs(8));
    Ok(())
}
fn worker(mode: &str, address: &str, port: u16) -> Result<()> {
    ensure!(port != 8000 && port != 7860, "forbidden fixture port");
    let address = SocketAddr::new(address.parse()?, port);
    match mode {
        "listen" => { let socket = TcpListener::bind(address)?; ready(socket.local_addr()?.port())?; drop(socket); }
        "udp" => { let socket = UdpSocket::bind(address)?; ready(socket.local_addr()?.port())?; drop(socket); }
        "established" => {
            let listener = TcpListener::bind(address)?;
            let local = listener.local_addr()?;
            let client = TcpStream::connect(local)?;
            let (accepted, _) = listener.accept()?;
            drop(listener);
            ready(local.port())?;
            drop((client, accepted));
        }
        "bound" => {
            let SocketAddr::V4(address) = address else { anyhow::bail!("bound fixture requires IPv4") };
            let raw = unsafe { libc::socket(libc::AF_INET, libc::SOCK_STREAM, 0) };
            ensure!(raw >= 0, "bound fixture socket failed");
            let fd = unsafe { OwnedFd::from_raw_fd(raw) };
            let mut sockaddr: libc::sockaddr_in = unsafe { std::mem::zeroed() };
            sockaddr.sin_len = std::mem::size_of_val(&sockaddr) as u8;
            sockaddr.sin_family = libc::AF_INET as u8;
            sockaddr.sin_port = address.port().to_be();
            sockaddr.sin_addr.s_addr = u32::from_ne_bytes(address.ip().octets());
            let size = std::mem::size_of_val(&sockaddr) as libc::socklen_t;
            ensure!(unsafe { libc::bind(fd.as_raw_fd(), (&sockaddr as *const libc::sockaddr_in).cast(), size) } == 0,
                "bound fixture bind failed");
            let mut size = size;
            ensure!(unsafe { libc::getsockname(fd.as_raw_fd(), (&mut sockaddr as *mut libc::sockaddr_in).cast(), &mut size) } == 0,
                "bound fixture getsockname failed");
            ready(u16::from_be(sockaddr.sin_port))?;
            drop(fd);
        }
        _ => anyhow::bail!("unknown fixture mode"),
    }
    Ok(())
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    if args.get(1).map(String::as_str) == Some("worker") {
        let result = (|| worker(args.get(2).context("mode")?, args.get(3).context("address")?,
            args.get(4).context("port")?.parse()?))();
        if let Err(error) = result {
            let errno = error.downcast_ref::<std::io::Error>().and_then(|e| e.raw_os_error());
            emit(json!({"worker_unavailable":true,"errno":errno}));
        }
    } else if let Err(error) = if args.get(1).map(String::as_str) == Some("multiple-families") {
        multiple_families()
    } else { run() } {
        emit(json!({"owned_listener_smoke":"failed","error":format!("{error:#}"),"global_visibility_certified":false}));
        std::process::exit(1);
    }
}

