use anyhow::{Context, Result, ensure};
use media_inference_lab::process_scope::{self, CommandSpec, OwnedProcess};
use serde_json::json;
use std::{collections::BTreeMap, fs::OpenOptions, io::{Read, Write}, os::unix::fs::OpenOptionsExt, path::PathBuf, time::{Duration, Instant}};
struct Owner { actor: OwnedProcess, end: Instant, done: bool }
impl Owner {
    fn finish(&mut self) -> Result<()> {
        if self.done { return Ok(()); }
        self.done=true;
        let settlement=self.actor.settle(self.end,Duration::from_millis(100),&mut ||Ok(()))?;
        println!("{}",json!({"pid":self.actor.pid(),"settlement":settlement}));
        ensure!(settlement.complete,"owned diagnostic fixture accounting incomplete");
        Ok(())
    }
}
impl Drop for Owner { fn drop(&mut self) { let _=self.finish(); } }
fn spawn(spec:&CommandSpec)->Result<Owner>{
    let end=Instant::now()+Duration::from_secs(12);
    let attempt=OwnedProcess::spawn_with_deadline(spec,Instant::now()+Duration::from_secs(2),&mut ||Ok(()))?;
    let owner=Owner{actor:attempt.process,end,done:false};
    ensure!(attempt.failure.is_none(),"owned diagnostic spawn failed");
    Ok(owner)
}
fn main()->Result<()> {
    let root=std::env::current_dir()?;
    let driver=root.join("owned-listener-proof");
    let mut fixture=spawn(&CommandSpec{executable:driver,args:vec!["worker".into(),"listen".into(),"0.0.0.0".into(),"0".into()],cwd:root.clone(),environment:BTreeMap::new()})?;
    let expected=fixture.actor.identity()?;
    let deadline=Instant::now()+Duration::from_secs(2);
    let mut ready=Vec::new();
    loop {
        ensure!(Instant::now()<deadline,"diagnostic fixture readiness expired");
        let mut bytes=[0u8;512];
        match fixture.actor.stdout.as_mut().context("stdout")?.read(&mut bytes){
            Ok(0)=>anyhow::bail!("fixture exited before readiness"),
            Ok(n)=>{ensure!(ready.len()+n<=4096,"readiness overflow");ready.extend_from_slice(&bytes[..n]);if ready.ends_with(b"\n"){break;}},
            Err(e) if e.kind()==std::io::ErrorKind::WouldBlock=>{}, Err(e)=>return Err(e.into()),
        }
        std::thread::sleep(Duration::from_millis(2));
    }
    let value:serde_json::Value=serde_json::from_slice(&ready)?;
    let port=value["port"].as_u64().context("port")?;
    ensure!(port>0&&port<=65535&&port!=8000&&port!=7860,"excluded port");
    let spec=CommandSpec{executable:PathBuf::from("/usr/sbin/lsof"),args:vec!["-O".into(),"-nP".into(),"+c".into(),"0".into(),format!("-iTCP:{port}"),"-sTCP:LISTEN".into(),"-Fpcn".into()],cwd:root.clone(),environment:BTreeMap::new()};
    let start=Instant::now();let end=start+Duration::from_millis(500);
    let attempt=OwnedProcess::spawn_with_deadline(&spec,end,&mut ||Ok(()))?;
    let mut helper=Owner{actor:attempt.process,end:start+Duration::from_secs(3),done:false};
    let mut stdout=Vec::new();let mut stderr=Vec::new();let mut total=0usize;
    let capture=(||->Result<()>{
        ensure!(attempt.failure.is_none(),"helper enrollment failed");
        loop {
            ensure!(Instant::now()<end,"diagnostic observation expired");
            let exited=helper.actor.exited_unreaped()?;
            for (stream,target) in [(&mut helper.actor.stdout,&mut stdout),(&mut helper.actor.stderr,&mut stderr)]{
                if let Some(stream)=stream {loop {let mut bytes=[0u8;4096];match stream.read(&mut bytes){
                    Ok(0)=>break,Ok(n)=>{total+=n;ensure!(total<=65536,"diagnostic capture exceeds bound");target.extend_from_slice(&bytes[..n]);},
                    Err(e) if e.kind()==std::io::ErrorKind::WouldBlock=>break,Err(e)=>return Err(e.into()),
                }}}
            }
            if exited{break;}
            std::thread::sleep(Duration::from_millis(2));
        }
        Ok(())
    })();
    for (name,bytes) in [("diagnostic-private.stdout",&stdout),("diagnostic-private.stderr",&stderr)]{
        let mut file=OpenOptions::new().write(true).create_new(true).mode(0o600).open(root.join(name))?;
        file.write_all(bytes)?;
    }
    helper.finish()?;
    let unchanged=process_scope::verify_identity(&expected)?.same_process(&expected);
    println!("{}",json!({"kind":"private_diagnostic_only_not_admission_proof","port":port,"owner":expected,"unchanged":unchanged,"elapsed_us":start.elapsed().as_micros(),"stdout_bytes":stdout.len(),"stderr_bytes":stderr.len(),"capture_error":capture.as_ref().err().map(|e|format!("{e:#}"))}));
    fixture.finish()?;capture?;ensure!(unchanged,"fixture identity changed");Ok(())
}

