/* Throwaway owned-PID prototype, not a production collector or control API.
 * All kernel structures and selectors come from the installed Apple SDK.
 * This deliberately does not expose argv/env, enumerate PIDs, or signal.
 */
#include <sys/types.h>
#include <sys/sysctl.h>
#include <sys/proc.h>
#include <sys/proc_info.h>
#include <libproc.h>
#include <errno.h>
#include <stdint.h>
#include <stddef.h>
#include <string.h>

_Static_assert(PROC_PIDPATHINFO_MAXSIZE == 4096, "update transfer record for SDK path size");
_Static_assert(ESRCH == 3 && EPERM == 1 && EACCES == 13, "SDK errno values changed");
_Static_assert(SIDL == 1 && SRUN == 2 && SSLEEP == 3 && SSTOP == 4 && SZOMB == 5,
    "SDK process states changed");

/* Our own FFI transfer record; NOT a reconstruction of a kernel structure. */
struct metadata_observation {
    int64_t before[8]; /* rc, errno, size, SDK size, pid, start sec/usec, state */
    int64_t path_result[2]; /* return value, errno captured before next query */
    int64_t after[8];
    int64_t short_result[6]; /* bytes, errno, SDK size, pid, state, arg */
    unsigned char path[PROC_PIDPATHINFO_MAXSIZE];
};

size_t metadata_observation_size(void) { return sizeof(struct metadata_observation); }
size_t metadata_path_capacity(void) { return PROC_PIDPATHINFO_MAXSIZE; }

static void birth(pid_t pid, int64_t out[8]) {
    struct kinfo_proc info;
    memset(&info, 0, sizeof(info));
    size_t length = sizeof(info);
    int mib[4] = {CTL_KERN, KERN_PROC, KERN_PROC_PID, pid};
    errno = 0;
    const int rc = sysctl(mib, 4, &info, &length, NULL, 0);
    const int saved_errno = errno;
    out[0] = rc;
    out[1] = saved_errno;
    out[2] = (int64_t)length;
    out[3] = (int64_t)sizeof(info);
    /* Do not interpret partial, zero/filtered, or failed kernel responses. */
    if (rc == 0 && length == sizeof(info)) {
        out[4] = info.kp_proc.p_pid;
        out[5] = info.kp_proc.p_starttime.tv_sec;
        out[6] = info.kp_proc.p_starttime.tv_usec;
        out[7] = info.kp_proc.p_stat;
    }
}

/* Caller must supply ONLY a PID retained from its own OwnedProcess spawn.
 * A post-reap call is read-only; PID reuse stays an explicit race limitation.
 */
void metadata_observe_owned(int32_t pid, struct metadata_observation *out) {
    memset(out, 0, sizeof(*out));
    if (pid <= 1) {
        out->before[0] = -1;
        out->before[1] = EINVAL;
        return;
    }
    birth(pid, out->before);
    errno = 0;
    const int length = proc_pidpath(pid, out->path, sizeof(out->path));
    const int path_errno = errno; /* MUST precede every other libc/kernel call. */
    out->path_result[0] = length;
    out->path_result[1] = path_errno;
    birth(pid, out->after);

    struct proc_bsdshortinfo short_info;
    memset(&short_info, 0, sizeof(short_info));
    errno = 0;
    const int bytes = proc_pidinfo(pid, PROC_PIDT_SHORTBSDINFO, 1,
        &short_info, sizeof(short_info));
    const int short_errno = errno;
    out->short_result[0] = bytes;
    out->short_result[1] = short_errno;
    out->short_result[2] = sizeof(short_info);
    out->short_result[5] = 1; /* live + zombie lookup, not ordinary arg=0 */
    if (bytes == (int)sizeof(short_info)) {
        out->short_result[3] = short_info.pbsi_pid;
        out->short_result[4] = short_info.pbsi_status;
    }
}

