/* Finite, nonforking, CPU-only owned fixture. No sockets or process queries. */
#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>

static uint64_t millis(void) {
    struct timespec t;
    if (clock_gettime(CLOCK_MONOTONIC, &t) != 0) _exit(70);
    return (uint64_t)t.tv_sec * 1000 + (uint64_t)t.tv_nsec / 1000000;
}

int main(int argc, char **argv) {
    if (argc != 2 || argv[1][0] != '/') return 64;
    const uint64_t deadline = millis() + 5000;
    while (millis() < deadline) {
        struct stat st;
        if (lstat(argv[1], &st) == 0) return S_ISREG(st.st_mode) ? 0 : 65;
        if (errno != ENOENT) return 66;
        struct timespec delay = {0, 2000000};
        (void)nanosleep(&delay, NULL);
    }
    return 67; /* Finite fallback exit is not a successful release receipt. */
}

