// Throwaway proof driver. Link to the real repository library; no copied owner.
// No CLI PID input, global enumeration, sockets, grants, or native admission.
use media_inference_lab::process_scope::{CommandSpec, OwnedProcess, ProcessIdentity, Settlement};
use std::collections::BTreeMap;
use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
use std::path::{Component, Path, PathBuf};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

type Result<T, E = String> = std::result::Result<T, E>;
const OBSERVATION_CAP: Duration = Duration::from_millis(500);
const CLEANUP_CAP: Duration = Duration::from_secs(8);
const ESRCH: i64 = 3; // Darwin errno; bridge obtains actual errno from SDK/libc.
const EPERM: i64 = 1;
const EACCES: i64 = 13;

#[repr(C)]
#[derive(Clone, Debug)]
struct Raw {
    before: [i64; 8],
    path_result: [i64; 2],
    after: [i64; 8],
    short_result: [i64; 6],
    path: [u8; 4096],
}
unsafe extern "C" {
    fn metadata_observation_size() -> usize;
    fn metadata_path_capacity() -> usize;
    fn metadata_observe_owned(pid: i32, result: *mut Raw);
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Outcome { Present, Nonmatch, AbsentAtShortLookup, Unavailable(&'static str) }
#[derive(Clone, Copy, Debug)]
struct Birth { pid: u32, seconds: u64, micros: u64, state: i64 }

fn need(condition: bool, message: &str) -> Result<()> {
    if condition { Ok(()) } else { Err(message.to_owned()) }
}
fn text(error: impl std::fmt::Display) -> String { error.to_string() }
fn denied(error: i64) -> bool { error == EPERM || error == EACCES }

fn birth(raw: &[i64; 8], pid: u32, now: u64) -> std::result::Result<Option<Birth>, &'static str> {
    if raw[0] != 0 { return Err("sysctl_error_sticky"); }
    if raw[2] == 0 { return Ok(None); } // Empty/filtered is NOT absence.
    if raw[3] <= 0 || raw[2] != raw[3] { return Err("metadata_size"); }
    if raw[4] != i64::from(pid) { return Err("metadata_pid"); }
    if raw[5] <= 0 || raw[5] as u64 > now || !(0..1_000_000).contains(&raw[6]) {
        return Err("metadata_starttime");
    }
    if !(1..=5).contains(&raw[7]) { return Err("metadata_state"); }
    Ok(Some(Birth { pid, seconds: raw[5] as u64, micros: raw[6] as u64, state: raw[7] }))
}
fn same_birth(b: Birth, expected: &ProcessIdentity) -> bool {
    b.pid == expected.pid && b.seconds == expected.start_seconds && b.micros == expected.start_subseconds
}
fn unambiguous_path(path: &Path) -> bool {
    path.is_absolute() && !path.components().any(|c| matches!(c, Component::ParentDir))
        && !path.as_os_str().as_bytes().windows(3).any(|w| w == b"/./")
}

// Pure classification. Synthetic cases call ONLY this function; no signals or queries.
fn classify(raw: &Raw, expected: &ProcessIdentity, prefix: &Path, now: u64) -> Outcome {
    use Outcome::*;
    if denied(raw.before[1]) || denied(raw.after[1]) || denied(raw.path_result[1]) || denied(raw.short_result[1]) {
        return Unavailable("denied_read_sticky");
    }
    let before = match birth(&raw.before, expected.pid, now) { Ok(v) => v, Err(e) => return Unavailable(e) };
    let after = match birth(&raw.after, expected.pid, now) { Ok(v) => v, Err(e) => return Unavailable(e) };
    if before.into_iter().chain(after).any(|b| !same_birth(b, expected)) {
        return Unavailable("birth_mismatch");
    }
    let short = raw.short_result;
    if short[5] != 1 { return Unavailable("short_lookup_not_live_and_zombie"); }
    let missing = short[0] == 0 && short[1] == ESRCH;
    if !missing && (short[0] <= 0 || short[2] <= 0 || short[0] != short[2]
        || short[3] != i64::from(expected.pid) || !(1..=5).contains(&short[4])) {
        return Unavailable("short_lookup_unavailable");
    }
    let length = raw.path_result[0];
    let path = if length > 0 && (length as usize) < raw.path.len() - 1 {
        let length = length as usize;
        if raw.path.iter().position(|b| *b == 0) != Some(length) { return Unavailable("path_truncated_or_ambiguous"); }
        let p = Path::new(std::ffi::OsStr::from_bytes(&raw.path[..length]));
        if !unambiguous_path(p) { return Unavailable("path_not_absolute_or_ambiguous"); }
        Some(p)
    } else if length == 0 && raw.path_result[1] == ESRCH {
        None // PATHINFO ESRCH alone is NEVER absence.
    } else {
        return Unavailable("path_unavailable");
    };
    // A missing live+zombie lookup is a later bounded snapshot, not historical
    // identity proof. It cannot erase any denied/invalid/mismatched read above.
    if missing { return AbsentAtShortLookup; }
    let (Some(before), Some(after)) = (before, after) else { return Unavailable("empty_metadata_not_absence"); };
    if before.state == 5 || after.state == 5 || short[4] == 5 { return Unavailable("zombie_not_absence"); }
    let Some(path) = path else { return Unavailable("path_esrch_with_existing_pid"); };
    if !unambiguous_path(prefix) { return Unavailable("ambiguous_prefix"); }
    if path.starts_with(prefix) { Present } else { Nonmatch }
}

fn classify_batch(rows: &[(u32, Outcome)]) -> Outcome {
    let mut seen = std::collections::BTreeSet::new();
    for (pid, outcome) in rows {
        if *pid <= 1 || !seen.insert(*pid) { return Outcome::Unavailable("duplicate_or_ambiguous_pid"); }
        if matches!(outcome, Outcome::Unavailable(_)) { return *outcome; }
    }
    if rows.iter().any(|(_, o)| *o == Outcome::Present) { Outcome::Present } else { Outcome::Nonmatch }
}

struct Fixture {
    actor: OwnedProcess,
    identity: Option<ProcessIdentity>,
    release: PathBuf,
    cleanup_deadline: Instant,
    settled: Option<Settlement>,
}
struct Harness { fixtures: Vec<Fixture>, receipt: File, root: PathBuf, binaries: PathBuf }
impl Harness {
    fn record(&mut self, value: impl std::fmt::Display) -> Result<()> {
        writeln!(self.receipt, "{value}").map_err(text)?;
        self.receipt.flush().map_err(text)
    }
    fn spawn(&mut self, directory: &str, missing_executable: bool) -> Result<usize> {
        let index = self.fixtures.len();
        let release = self.root.join(format!("release-{index}"));
        let start = Instant::now();
        let cleanup_deadline = start + CLEANUP_CAP; // Enrolled BEFORE spawn; never reset.
        let executable = self.binaries.join(directory).join(if missing_executable { "missing-owned-fixture" } else { "fixture" });
        let spec = CommandSpec { executable, args: vec![release.to_string_lossy().into_owned()],
            cwd: self.root.clone(), environment: BTreeMap::new() };
        let attempt = OwnedProcess::spawn_with_deadline(&spec, start + Duration::from_secs(2), &mut || Ok(())).map_err(text)?;
        let (actor, failure) = attempt.into_parts();
        // Retain ownership BEFORE fallible identity/receipt/assertion operations.
        self.fixtures.push(Fixture { actor, identity: None, release, cleanup_deadline, settled: None });
        self.record(format!("spawn index={index} pid={} failure={failure:?} cleanup_cap_ms=8000", self.fixtures[index].actor.pid()))?;
        if missing_executable {
            need(failure.is_some(), "intentional missing executable unexpectedly spawned")?;
        } else {
            need(failure.is_none(), "owned fixture enrollment failed; retained for cleanup")?;
            let identity = self.fixtures[index].actor.identity().map_err(text)?;
            self.fixtures[index].identity = Some(identity.clone());
            self.record(format!("owned_identity index={index} {identity:?}"))?;
        }
        Ok(index)
    }
    fn observe(&mut self, index: usize, phase: &str) -> Result<(Raw, Outcome)> {
        let fixture = &self.fixtures[index];
        let expected = fixture.identity.as_ref().ok_or("no enrolled live identity")?;
        let mut raw: Raw = unsafe { std::mem::zeroed() };
        let start = Instant::now();
        unsafe { metadata_observe_owned(expected.pid as i32, &mut raw); }
        let elapsed = start.elapsed();
        let now = SystemTime::now().duration_since(UNIX_EPOCH).map_err(text)?.as_secs();
        let outcome = if elapsed > OBSERVATION_CAP { Outcome::Unavailable("observation_deadline") }
            else { classify(&raw, expected, &self.binaries.join("inside"), now) };
        self.record(format!("observed phase={phase} index={index} elapsed_us={} outcome={outcome:?} before={:?} after={:?} path_result={:?} short={:?}",
            elapsed.as_micros(), raw.before, raw.after, raw.path_result, raw.short_result))?;
        Ok((raw, outcome))
    }
    fn settle(&mut self, index: usize) -> Result<Settlement> {
        let fixture = &mut self.fixtures[index];
        let start = Instant::now();
        let result = fixture.actor.settle(fixture.cleanup_deadline, Duration::from_millis(100), &mut || Ok(())).map_err(text)?;
        fixture.settled = Some(result.clone()); // Retain even an incomplete receipt.
        self.record(format!("settlement index={index} elapsed_us={} {result:?}", start.elapsed().as_micros()))?;
        Ok(result)
    }
    fn cleanup_all(&mut self) -> bool {
        let mut complete = true;
        for index in 0..self.fixtures.len() {
            match self.settle(index) {
                Ok(result) => complete &= result.complete,
                Err(error) => {
                    complete = false;
                    let _ = self.record(format!("cleanup_error index={index} {error}"));
                }
            }
        }
        complete // Group absent alone MUST NOT count as complete.
    }
}

fn synthetic_cases(h: &mut Harness, real: &Raw, expected: &ProcessIdentity) -> Result<()> {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map_err(text)?.as_secs();
    let prefix = h.binaries.join("inside");
    let mut rows: Vec<(&str, Raw, ProcessIdentity, Outcome)> = Vec::new();
    let mut add = |name, change: fn(&mut Raw), want| { let mut r = real.clone(); change(&mut r); rows.push((name, r, expected.clone(), want)); };
    add("after_birth_reuse", |r| r.after[6] = (r.after[6] + 1) % 1_000_000, Outcome::Unavailable("birth_mismatch"));
    add("short_size", |r| r.before[2] -= 1, Outcome::Unavailable("metadata_size"));
    add("wrong_pid", |r| r.before[4] += 1, Outcome::Unavailable("metadata_pid"));
    add("invalid_usec", |r| r.before[6] = 1_000_000, Outcome::Unavailable("metadata_starttime"));
    add("zero_metadata_live", |r| r.before[2] = 0, Outcome::Unavailable("empty_metadata_not_absence"));
    add("path_esrch_live", |r| r.path_result = [0, ESRCH], Outcome::Unavailable("path_esrch_with_existing_pid"));
    add("path_esrch_zombie", |r| { r.path_result = [0, ESRCH]; r.short_result[4] = 5; }, Outcome::Unavailable("zombie_not_absence"));
    add("relative_path", |r| r.path[0] = b'x', Outcome::Unavailable("path_not_absolute_or_ambiguous"));
    add("truncated_path", |r| r.path_result[0] += 1, Outcome::Unavailable("path_truncated_or_ambiguous"));
    add("sysctl_denied_then_missing", |r| { r.before[0] = -1; r.before[1] = EPERM; r.short_result[0] = 0; r.short_result[1] = ESRCH; }, Outcome::Unavailable("denied_read_sticky"));
    add("path_denied_then_missing", |r| { r.path_result = [0, EACCES]; r.short_result[0] = 0; r.short_result[1] = ESRCH; }, Outcome::Unavailable("denied_read_sticky"));
    add("short_denied", |r| { r.short_result[0] = 0; r.short_result[1] = EPERM; }, Outcome::Unavailable("denied_read_sticky"));
    add("short_arg_zero", |r| r.short_result[5] = 0, Outcome::Unavailable("short_lookup_not_live_and_zombie"));
    add("zero_metadata_missing_live_and_zombie", |r| { r.before[2] = 0; r.after[2] = 0; r.path_result = [0, ESRCH]; r.short_result[0] = 0; r.short_result[1] = ESRCH; }, Outcome::AbsentAtShortLookup);
    let mut mismatched = expected.clone();
    mismatched.start_subseconds = (mismatched.start_subseconds + 1) % 1_000_000;
    rows.push(("synthetic_expected_birth_no_control", real.clone(), mismatched, Outcome::Unavailable("birth_mismatch")));
    for (name, raw, expected, wanted) in rows {
        let got = classify(&raw, &expected, &prefix, now);
        h.record(format!("synthetic name={name} outcome={got:?} wanted={wanted:?} no_query=true no_control=true"))?;
        need(got == wanted, "synthetic classification mismatch")?;
    }
    for rows in [vec![(expected.pid, Outcome::Present), (expected.pid, Outcome::Nonmatch)], vec![(0, Outcome::Nonmatch)]] {
        let got = classify_batch(&rows);
        h.record(format!("synthetic ambiguous_batch outcome={got:?} no_query=true no_control=true"))?;
        need(got == Outcome::Unavailable("duplicate_or_ambiguous_pid"), "ambiguous candidate batch was accepted")?;
    }
    Ok(())
}

fn run(h: &mut Harness) -> Result<()> {
    need(unsafe { metadata_observation_size() } == std::mem::size_of::<Raw>(), "C/Rust transfer ABI size mismatch")?;
    need(unsafe { metadata_path_capacity() } == 4096, "SDK path capacity changed")?;
    h.record("source_only_candidate=true cross_user_visibility=unproved deployed_policy=unproved production_changes=none")?;
    for (directory, wanted) in [("inside", Outcome::Present), ("outside", Outcome::Nonmatch), ("inside-sibling", Outcome::Nonmatch)] {
        let index = h.spawn(directory, false)?;
        let expected = h.fixtures[index].identity.clone().ok_or("identity unavailable")?;
        let (raw, got) = h.observe(index, "live_birth_bracket")?;
        need(got == wanted, "real live path classification failed")?;
        h.fixtures[index].actor.check_membership().map_err(text)?;
        let after = h.fixtures[index].actor.identity().map_err(text)?;
        need(expected.same_process(&after), "observer interfered with owned identity")?;
        h.record(format!("non_interference index={index} same_process=true live=true"))?;
        if directory == "inside" { synthetic_cases(h, &raw, &expected)?; }
        OpenOptions::new().write(true).create_new(true).mode(0o600).open(&h.fixtures[index].release).map_err(text)?;
        let exit_deadline = (Instant::now() + Duration::from_secs(1)).min(h.fixtures[index].cleanup_deadline);
        while !h.fixtures[index].actor.exited_unreaped().map_err(text)? {
            need(Instant::now() < exit_deadline, "finite fixture did not exit before zombie observation cap")?;
            std::thread::sleep(Duration::from_millis(2));
        }
        let (zombie, outcome) = h.observe(index, "owned_unreaped_zombie")?;
        need(zombie.short_result[0] == zombie.short_result[2] && zombie.short_result[3] == i64::from(expected.pid) && zombie.short_result[4] == 5,
            "SHORTBSD arg=1 did not expose exact owned zombie")?;
        // Real zombie ABI availability is recorded independently from denial behavior.
        h.record(format!("real_zombie_kinfo before_exact={} after_exact={} birth_equal={}", zombie.before[2] == zombie.before[3], zombie.after[2] == zombie.after[3],
            zombie.before[5..7] == raw.before[5..7] && zombie.after[5..7] == raw.before[5..7]))?;
        let now = SystemTime::now().duration_since(UNIX_EPOCH).map_err(text)?.as_secs();
        for metadata in [&zombie.before, &zombie.after] {
            match birth(metadata, expected.pid, now) {
                Ok(Some(b)) => need(same_birth(b, &expected) && b.state == 5, "zombie metadata changed birth or state")?,
                Ok(None) => h.record("real_zombie_kinfo unavailable_empty=true short_zombie_still_prevents_absence=true")?,
                Err(error) => return Err(format!("real zombie metadata ABI read failed: {error}")),
            }
        }
        need(matches!(outcome, Outcome::Unavailable(_)), "zombie became an absence or path nonmatch")?;
        let settlement = h.settle(index)?;
        need(settlement.complete && settlement.leader_reaped && settlement.group_absent && settlement.exit_code == Some(0), "normal fixture settlement incomplete")?;
        let (_, reaped) = h.observe(index, "owned_post_reap_read_only")?;
        need(reaped == Outcome::AbsentAtShortLookup, "post-reap bounded missing observation unavailable; no retry or control")?;
        let cached = h.settle(index)?;
        need(format!("{cached:?}") == format!("{settlement:?}"), "cached settlement changed")?;
        h.record(format!("post_reap_cleanup index={index} cached_noop=true no_post_reap_control=true"))?;
    }
    // Exercise both error return and unwind with a genuinely retained live actor.
    for panic_case in [false, true] {
        let index = h.spawn("outside", false)?;
        let failure = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| -> Result<()> {
            if panic_case { panic!("intentional owned fixture unwind"); }
            Err("intentional owned fixture error".to_owned())
        }));
        need(!matches!(failure, Ok(Ok(()))), "intentional fixture failure did not occur")?;
        let settlement = h.settle(index)?;
        need(settlement.complete, "failure/unwind fixture cleanup incomplete")?;
        h.record(format!("failure_cleanup index={index} panic={panic_case} known_identity_retained=true complete=true"))?;
    }
    let failed_spawn = h.spawn("outside", true)?;
    let settlement = h.settle(failed_spawn)?;
    // Enrollment/exec failure may be sticky even when its known group is gone.
    need(settlement.leader_reaped && settlement.group_absent, "failed spawn known child cleanup incomplete")?;
    h.record(format!("failed_spawn_cleanup index={failed_spawn} qualified_complete={} retained_failure={:?}", settlement.complete, settlement.failure))?;
    Ok(())
}

fn main() {
    let result = setup_and_run();
    if let Err(error) = result { eprintln!("owned metadata proof failed: {error}"); std::process::exit(1); }
}
fn setup_and_run() -> Result<()> {
    let args: Vec<_> = std::env::args_os().collect();
    need(args.len() == 3, "usage: metadata-runner PRIVATE_BINARIES NEW_PRIVATE_RECEIPT_DIR")?;
    let binaries = fs::canonicalize(&args[1]).map_err(text)?;
    let root_input = PathBuf::from(&args[2]);
    need(root_input.is_absolute(), "receipt directory must be absolute")?;
    fs::DirBuilder::new().mode(0o700).create(&root_input).map_err(text)?;
    let root = fs::canonicalize(root_input).map_err(text)?;
    let receipt = OpenOptions::new().write(true).create_new(true).mode(0o600).open(root.join("receipt.txt")).map_err(text)?;
    let mut h = Harness { fixtures: Vec::new(), receipt, root, binaries };
    let run_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| run(&mut h)));
    // No early return can skip fixture-owner cleanup after a successful fork.
    let cleanup_complete = h.cleanup_all();
    let success = matches!(&run_result, Ok(Ok(())));
    h.record(format!("final behavior_pass={success} all_settlements_qualified_complete={cleanup_complete} retained_actors={}", h.fixtures.len()))?;
    match run_result {
        Ok(Ok(())) if cleanup_complete => Ok(()),
        Ok(Ok(())) => Err("behavior passed but strict fixture settlement remains incomplete".to_owned()),
        Ok(Err(error)) => Err(error),
        Err(_) => Err("driver unwound; retained fixture cleanup receipts recorded".to_owned()),
    }
}
